    static void report(){try{REPORT.addProperty("mode",MODE);REPORT.addProperty("phase",phase);REPORT.addProperty("owner_profile_used",false);REPORT.addProperty("geometry_sha256",EitanData.SHA256);REPORT.add("samples",SAMPLES);Files.writeString(mc().gameDirectory.toPath().resolve("eitan-drive-"+MODE+".json"),new GsonBuilder().setPrettyPrinting().create().toJson(REPORT));}catch(Exception e){throw new IllegalStateException(e);}}
    static void finish(boolean pass,String error){KeyMapping.releaseAll();if(!pass&&mc().level!=null)EitanDriveNative.shot("failure");REPORT.addProperty("passed",pass);REPORT.addProperty("error",error);REPORT.addProperty("peak_m_s",peak);REPORT.addProperty("max_tilt_rad",tilt);REPORT.addProperty("max_lateral_m",lateral);if(Double.isFinite(rideMin)){REPORT.addProperty("ride_min_y",rideMin);REPORT.addProperty("ride_max_y",rideMax);}REPORT.addProperty("min_driver_health",minHealth);REPORT.add("view_trace",EitanViewTrace.result());if(c!=null){REPORT.addProperty("fuel_ticks",c.fuelTicks);REPORT.addProperty("brake_status",c.brakeStatus());}report();closing=true;if(mc().level!=null)mc().level.disconnect();mc().disconnect(new TitleScreen());}
    static int height(int x,int z){world.getChunk(x>>4,z>>4);return world.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,x,z);}
    static void selectRoute(){
        var found=world.findClosestBiome3d(b->b.is(Biomes.SUNFLOWER_PLAINS),new BlockPos(world.getSharedSpawnPos().getX(),world.getSeaLevel()+1,world.getSharedSpawnPos().getZ()),8192,32,world.getHeight());
        need(found!=null,"No plains biome found at the surface within the bounded search");var centre=found.getFirst();
        REPORT.addProperty("biome",found.getSecond().unwrapKey().orElseThrow().location().toString());
        REPORT.addProperty("biome_anchor_y",centre.getY());REPORT.addProperty("biome_anchor_x",centre.getX());REPORT.addProperty("biome_anchor_z",centre.getZ());var scan=new JsonArray();REPORT.add("route_scan",scan);
        int examined=0;
        for(int crossLimit:new int[]{1,2})for(int dz=-128;dz<=128;dz+=8)for(int dx=-64;dx<=64;dx+=8){
            int x=centre.getX()+dx,z=centre.getZ()+dz,lo=Integer.MAX_VALUE,hi=Integer.MIN_VALUE;boolean usable=true;String rejection="";
            var profile=new JsonArray();int centreLo=Integer.MAX_VALUE,centreHi=Integer.MIN_VALUE;int[] previous=null;
            for(int i=0;i<=LEG_METRES+4&&usable;i++){
                int[] row=new int[5];for(int j=0;j<5;j++){row[j]=height(x+j-2,z-i);var ground=world.getBlockState(new BlockPos(x+j-2,row[j]-1,z-i));if(!ground.getFluidState().isEmpty()){usable=false;rejection="water";}lo=Math.min(lo,row[j]);hi=Math.max(hi,row[j]);if(previous!=null&&Math.abs(row[j]-previous[j])>1){usable=false;rejection="longitudinal_step_over_1m";}}
                if(Arrays.stream(row).max().orElseThrow()-Arrays.stream(row).min().orElseThrow()>crossLimit){usable=false;rejection="cross_span_over_"+crossLimit;}
                centreLo=Math.min(centreLo,row[2]);centreHi=Math.max(centreHi,row[2]);if(i%2==0)profile.add(row[2]);previous=row;
            }
            examined++;if(examined%8==0)System.out.println("EITAN_FIELD_SCAN candidates="+examined);
            var candidate=new JsonObject();candidate.addProperty("x",x);candidate.addProperty("z",z);candidate.addProperty("cross_limit",crossLimit);candidate.addProperty("min_y",lo);candidate.addProperty("max_y",hi);candidate.add("partial_height_profile",profile);scan.add(candidate);
            if(!usable||centreHi-centreLo<2||centreHi-centreLo>8){candidate.addProperty("rejected",!usable?rejection:"centre_height_span_outside_2_to_8m");continue;}
            int initialLo=Integer.MAX_VALUE,initialHi=Integer.MIN_VALUE;
            for(int bx=-2;bx<=2;bx++)for(int bz=-4;bz<=4;bz++){int h=height(x+bx,z+bz);initialLo=Math.min(initialLo,h);initialHi=Math.max(initialHi,h);}
            if(initialHi-initialLo>3){candidate.addProperty("rejected","starting_footprint_span_"+(initialHi-initialLo));continue;}
            var site=new net.minecraft.world.phys.AABB(x-2,initialHi+2,z-5,x+3,initialHi+6,z+6);
            if(!world.getEntities(null,site).isEmpty()){candidate.addProperty("rejected","entity_in_assembly_site");continue;}
            candidate.addProperty("accepted",true);REPORT.addProperty("route_selection_cross_span_limit_m",crossLimit);REPORT.addProperty("actual_surface_biome",world.getBiome(new BlockPos(x,height(x,z),z)).unwrapKey().orElseThrow().location().toString());routeX=x;routeZ=z;minY=lo-3;maxY=Math.max(hi,initialHi)+8;
            REPORT.addProperty("route_candidates_examined",examined);REPORT.addProperty("leg_length_m",LEG_METRES);REPORT.addProperty("planned_round_trips",ROUND_TRIPS);REPORT.addProperty("initial_footprint_span_m",initialHi-initialLo);REPORT.addProperty("route_x",x);REPORT.addProperty("route_z",z);REPORT.addProperty("terrain_min_y",lo);REPORT.addProperty("terrain_max_y",hi);REPORT.addProperty("route_centre_min_y",centreLo);REPORT.addProperty("route_centre_max_y",centreHi);REPORT.addProperty("hash_min_z",routeZ-LEG_METRES-8);REPORT.addProperty("hash_max_z",routeZ+8);REPORT.addProperty("hash_min_y",minY);REPORT.addProperty("hash_max_y",maxY);REPORT.add("route_height_profile_every_2m",profile);
            need(x==-640&&z==704,"Regression route differs from the original failed climb");REPORT.addProperty("world_seed",world.getSeed());assemblyY=initialHi+2;terrainHash();
            player().getAbilities().flying=true;player().onUpdateAbilities();player().teleportTo(world,x+16,initialHi+12,z+12,Set.of(),180,20);
            return;
        }
        throw new IllegalStateException("No natural rolling route matched the declared criteria after "+examined+" candidates");
    }
    static String terrainHash(){try{for(int cx=(routeX-12)>>4;cx<=(routeX+12)>>4;cx++)for(int cz=(routeZ-LEG_METRES-8)>>4;cz<=(routeZ+8)>>4;cz++)world.getChunk(cx,cz);var hash=MessageDigest.getInstance("SHA-256");var pos=new BlockPos.MutableBlockPos();for(int x=routeX-12;x<=routeX+12;x++)for(int z=routeZ-LEG_METRES-8;z<=routeZ+8;z++)for(int y=minY;y<=maxY;y++){pos.set(x,y,z);hash.update(world.getBlockState(pos).toString().getBytes(StandardCharsets.UTF_8));hash.update((byte)0);}return HexFormat.of().formatHex(hash.digest());}catch(Exception e){throw new IllegalStateException(e);}}
    static void locate(){EitanDriveNative.world=world;EitanDriveNative.locate();c=EitanDriveNative.c;body=EitanDriveNative.body;}
    static void mount(){player().setGameMode(GameType.SURVIVAL);player().getAbilities().flying=false;player().onUpdateAbilities();player().setHealth(20);player().getFoodData().setFoodLevel(20);var p=c.world(-.68,.55,-2.21);player().teleportTo(world,p.x,p.y,p.z,Set.of(),180,28);need(EitanSeatEntity.mount(c,0,player()),"Field fixture could not mount driver");REPORT.addProperty("driver_mounted_by_fixture",true);REPORT.addProperty("survival_driver",true);}
    static void sample(){var p=point();rideMin=Math.min(rideMin,p.y);rideMax=Math.max(rideMax,p.y);peak=Math.max(peak,c.speed);var up=body.logicalPose().transformNormal(new Vector3d(0,1,0));tilt=Math.max(tilt,Math.acos(Math.clamp(up.y,-1,1)));minHealth=Math.min(minHealth,mc().player.getHealth());lateral=Math.max(lateral,Math.abs(p.x-start.x));need(up.y>Math.cos(Math.toRadians(55)),"Natural terrain rollover: up="+up+" point="+p);need(minHealth>19.9,"Driver took damage while seated: "+minHealth);need(Math.abs(p.x-start.x)<6,"Vehicle left the declared route corridor: "+p);need(p.y>REPORT.get("terrain_min_y").getAsInt()-3,"Vehicle fell below the natural terrain");need(mc().player.getVehicle() instanceof EitanSeatEntity seat&&seat.matches(c),"Natural drive lost its real passenger");if(ticks%10==0){var row=new JsonObject();row.addProperty("phase",phase);row.addProperty("tick",ticks);row.addProperty("x",p.x);row.addProperty("y",p.y);row.addProperty("z",p.z);row.addProperty("speed",c.speed);row.addProperty("health",mc().player.getHealth());row.addProperty("fps",mc().getFps());row.addProperty("steer",c.steer);row.addProperty("brake",c.brake);row.addProperty("clearance_lift",c.clearanceLift);row.addProperty("drive_effort",c.driveEffort);var springs=new JsonArray();for(var m:EitanData.MOUNTS)if(mc().level.getBlockEntity(c.origin().offset(m.pos())) instanceof EitanWheelEntity wheel)springs.add(wheel.getLerpedExtension(1));row.add("wheel_extensions",springs);SAMPLES.add(row);}}
    static void drive(boolean reverse){var p=point();double dz=reverse?10:-12,desired=Math.toDegrees(Math.atan2(-(start.x-p.x),dz))+(reverse?180:0);var front=body.logicalPose().transformNormal(new Vector3d(0,0,-1));double actual=Math.toDegrees(Math.atan2(-front.x,front.z));float error=net.minecraft.util.Mth.wrapDegrees((float)(desired-actual));mc().options.keyUp.setDown(!reverse);mc().options.keyDown.setDown(reverse);mc().options.keyLeft.setDown(reverse?error>2:error< -2);mc().options.keyRight.setDown(reverse?error< -2:error>2);}
    static void inspect(){try{
        var p=point();REPORT.addProperty("inspected_body_uuid",body.getUniqueId().toString());REPORT.addProperty("drive_effort",c.driveEffort);REPORT.addProperty("suspension_anchor",c.suspensionAnchor);REPORT.addProperty("spring_strength",c.suspensionStrength);REPORT.addProperty("body_mass",body.getMassTracker().getMass());REPORT.addProperty("body_x",p.x);REPORT.addProperty("body_y",p.y);REPORT.addProperty("body_z",p.z);REPORT.addProperty("body_up",body.logicalPose().transformNormal(new Vector3d(0,1,0)).toString());
        var terrain=new JsonArray();for(int x=(int)Math.floor(p.x)-3;x<=(int)Math.floor(p.x)+3;x++)for(int z=(int)Math.floor(p.z)-6;z<=(int)Math.floor(p.z)+7;z++){var v=new JsonArray();v.add(x);v.add(z);v.add(height(x,z));terrain.add(v);}REPORT.add("terrain_heights",terrain);
        var contacts=new JsonArray();var method=dev.ryanhcode.offroad.content.blocks.wheel_mount.WheelMountBlockEntity.class.getDeclaredMethod("computeMaxExtensionToTerrain",org.joml.Vector3dc.class,dev.ryanhcode.sable.companion.math.Pose3dc.class);method.setAccessible(true);
        for(var m:EitanData.MOUNTS)if(world.getBlockEntity(c.origin().offset(m.pos())) instanceof EitanWheelEntity w){var row=new JsonObject();row.addProperty("slot",m.slot());var a=w.physicalAnchor();var aw=body.logicalPose().transformPosition(a);row.addProperty("anchor",aw.toString());row.addProperty("ground_height",height((int)Math.floor(aw.x),(int)Math.floor(aw.z)));var result=method.invoke(w,new Vector3d(0,0,1).rotateY(w.yaw(1)),body.logicalPose());for(var getter:result.getClass().getDeclaredMethods())if(getter.getParameterCount()==0&&Set.of("maxExtension","normal","minInteractingBlock").contains(getter.getName())){getter.setAccessible(true);row.addProperty(getter.getName(),String.valueOf(getter.invoke(result)));}contacts.add(row);}REPORT.add("contacts",contacts);
        need(terrainHash().equals(terrainBefore),"Failed-scene terrain changed");REPORT.addProperty("failed_scene_terrain_unchanged",true);
    }catch(ReflectiveOperationException e){throw new IllegalStateException(e);}}
    static void save(){c.engine=false;c.sync();var p=point();REPORT.addProperty("body_uuid",body.getUniqueId().toString());REPORT.addProperty("saved_fuel",c.fuelTicks);REPORT.addProperty("saved_health",player().getHealth());REPORT.addProperty("saved_x",p.x);REPORT.addProperty("saved_y",p.y);REPORT.addProperty("saved_z",p.z);var poses=new JsonArray();for(float v:c.progress)poses.add(v);REPORT.add("saved_motion",poses);var hash=terrainHash();REPORT.addProperty("terrain_after_sha256",hash);if(!hash.equals(terrainBefore)){try{var before=JsonParser.parseString(Files.readString(mc().gameDirectory.toPath().resolve("field-terrain-before.json"))).getAsJsonArray();var changes=new JsonArray();int index=0,total=0;var pos=new BlockPos.MutableBlockPos();for(int x=routeX-12;x<=routeX+12;x++)for(int z=routeZ-LEG_METRES-8;z<=routeZ+8;z++)for(int y=minY;y<=maxY;y++){pos.set(x,y,z);var old=before.get(index++).getAsString();var now=world.getBlockState(pos).toString();if(!old.equals(now)){total++;if(changes.size()<2000){var change=new JsonObject();change.addProperty("pos",pos.toString());change.addProperty("before",old);change.addProperty("after",now);changes.add(change);}}}REPORT.addProperty("terrain_changed_blocks",total);REPORT.add("terrain_changes",changes);}catch(Exception e){throw new IllegalStateException(e);}}need(hash.equals(terrainBefore),"Natural terrain changed during assembly/drive");REPORT.addProperty("terrain_unchanged",true);world.getServer().saveEverything(false,true,true);REPORT.addProperty("saved",true);}
